  `price` bigint(20) unsigned NOT NULL,
  `warranty_type` varchar(50) DEFAULT NULL COMMENT '┘┘ê╪╣ ┌»╪د╪▒╪د┘╪ز█î: test, limited, lifetime',
  `warranty_duration` int(10) unsigned DEFAULT NULL COMMENT '┘à╪»╪ز ┌»╪د╪▒╪د┘╪ز█î ╪ذ┘ç ╪▒┘ê╪▓ (┘┘é╪╖ ╪ذ╪▒╪د█î limited)',
  `warranty_price` bigint(20) unsigned DEFAULT NULL COMMENT '┘ç╪▓█î┘┘ç ┌»╪د╪▒╪د┘╪ز█î',
  `min_quantity` int(10) unsigned NOT NULL DEFAULT 1,
  `max_quantity` int(10) unsigned DEFAULT NULL,
  `warranty_months` smallint(5) unsigned DEFAULT NULL,
  `check_months` smallint(5) unsigned DEFAULT NULL,
