  KEY `product_prices_price_type_id_foreign` (`price_type_id`),
  KEY `product_prices_check_period_id_foreign` (`check_period_id`),
  KEY `price_lookup_index` (`product_supplier_id`,`price_type_id`,`tier_index`),
  KEY `active_valid_index` (`is_active`,`valid_from`,`valid_until`),
  CONSTRAINT `product_prices_check_period_id_foreign` FOREIGN KEY (`check_period_id`) REFERENCES `check_periods` (`id`) ON DELETE SET NULL,
  CONSTRAINT `product_prices_price_type_id_foreign` FOREIGN KEY (`price_type_id`) REFERENCES `price_types` (`id`) ON DELETE SET NULL,
  CONSTRAINT `product_prices_product_id_foreign` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE,
  CONSTRAINT `product_prices_product_supplier_id_foreign` FOREIGN KEY (`product_supplier_id`) REFERENCES `product_supplier` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1129 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
