DROP TABLE IF EXISTS `product_supplier`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `product_supplier` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `product_id` bigint(20) unsigned NOT NULL,
  `supplier_id` bigint(20) unsigned NOT NULL,
  `sku` varchar(255) DEFAULT NULL COMMENT 'SKU ╪د╪«╪ز╪╡╪د╪╡█î ╪د█î┘ ╪ز╪ث┘à█î┘ظî┌ر┘┘╪»┘ç ╪ذ╪▒╪د█î ╪د█î┘ ┘à╪ص╪╡┘ê┘',
  `stock_quantity` int(11) DEFAULT NULL,
  `min_order_quantity` int(11) DEFAULT NULL,
  `max_order_quantity` int(11) DEFAULT NULL,
  `is_primary` tinyint(1) NOT NULL DEFAULT 0 COMMENT '╪ت█î╪د ╪ز╪ث┘à█î┘ظî┌ر┘┘╪»┘ç ╪د╪╡┘█î ╪د╪│╪ز╪ا',
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `warranty_type` enum('none','percentage','fixed','custom') NOT NULL DEFAULT 'none' COMMENT '┘┘ê╪╣ ┘à╪ص╪د╪│╪ذ┘ç ┘ç╪▓█î┘┘ç ┌»╪د╪▒╪د┘╪ز█î',
  `warranty_value` decimal(10,2) DEFAULT NULL COMMENT '┘à┘é╪»╪د╪▒ ╪»╪▒╪╡╪» █î╪د ┘à╪ذ┘╪║ ╪س╪د╪ذ╪ز ┌»╪د╪▒╪د┘╪ز█î',
  `has_warranty` tinyint(1) NOT NULL DEFAULT 0 COMMENT '╪ت█î╪د ┘à╪ص╪╡┘ê┘ ╪ذ╪د ┌»╪د╪▒╪د┘╪ز█î ╪╣╪▒╪╢┘ç ┘à█îظî╪┤┘ê╪»╪ا',
  `warranty_provider` enum('none','manufacturer','seller') NOT NULL DEFAULT 'none' COMMENT '╪د╪▒╪د╪خ┘çظî╪»┘ç┘╪»┘ç ┌»╪د╪▒╪د┘╪ز█î',
  `warranty_coverage_type` enum('full','limited','parts_only','service_only') NOT NULL DEFAULT 'full' COMMENT '┘┘ê╪╣ ┘╛┘ê╪┤╪┤ ┌»╪د╪▒╪د┘╪ز█î',
  `warranty_type_coverage` enum('test','limited','lifetime') NOT NULL DEFAULT 'limited' COMMENT '┘┘ê╪╣ ┌»╪د╪▒╪د┘╪ز█î: ╪ز╪│╪ز╪î ┘à╪»╪زظî╪»╪د╪▒╪î ┘à╪د╪»╪د┘àظî╪د┘╪╣┘à╪▒',
  `warranty_duration_days` int(11) DEFAULT NULL COMMENT '┘à╪»╪ز ┌»╪د╪▒╪د┘╪ز█î (╪▒┘ê╪▓)',
  `auto_calculate_tiers` tinyint(1) NOT NULL DEFAULT 0 COMMENT '┘╪╣╪د┘/╪║█î╪▒┘╪╣╪د┘ ┘à╪ص╪د╪│╪ذ┘ç ╪«┘ê╪»┌ر╪د╪▒ ╪ز█î╪▒╪د┌ء┘ç╪د',
  `tier_percentages` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '╪»╪▒╪╡╪»┘ç╪د█î ╪ز█î╪▒╪د┌ء┘ç╪د ┘╪│╪ذ╪ز ╪ذ┘ç ┘à╪▒╪ش╪╣' CHECK (json_valid(`tier_percentages`)),
  `tier_enabled` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '┘ê╪╢╪╣█î╪ز ┘╪╣╪د┘/╪║█î╪▒┘╪╣╪د┘ ┘ç╪▒ ╪ز█î╪▒╪د┌ء' CHECK (json_valid(`tier_enabled`)),
  `activated_at` timestamp NULL DEFAULT NULL,
  `deactivated_at` timestamp NULL DEFAULT NULL,
  `status` varchar(255) NOT NULL DEFAULT 'pending',
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `product_supplier_product_id_supplier_id_unique` (`product_id`,`supplier_id`),
  KEY `product_supplier_product_id_is_primary_index` (`product_id`,`is_primary`),
  KEY `product_supplier_supplier_id_is_active_index` (`supplier_id`,`is_active`),
  KEY `prod_supp_status_stock_idx` (`product_id`,`status`,`stock_quantity`),
  CONSTRAINT `product_supplier_product_id_foreign` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE,
  CONSTRAINT `product_supplier_supplier_id_foreign` FOREIGN KEY (`supplier_id`) REFERENCES `suppliers` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=415 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

