DROP TABLE IF EXISTS `products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `products` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `legacy_id` bigint(20) unsigned DEFAULT NULL,
  `supplier_id` bigint(20) unsigned DEFAULT NULL,
  `category_id` bigint(20) unsigned NOT NULL,
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `sku` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `short_description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `full_description` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `specifications` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `weight` decimal(8,2) DEFAULT NULL,
  `dimensions` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `quantity_tiers` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '╪ز█î╪▒╪د┌ء┘ç╪د█î ┘à╪ص╪╡┘ê┘ ╪ذ┘ç ╪╡┘ê╪▒╪ز JSON' CHECK (json_valid(`quantity_tiers`)),
  `packaging_unit_type` enum('carton','jean','jowab','package','bundle','roll','piece') NOT NULL DEFAULT 'carton' COMMENT '┘┘ê╪╣ ┘ê╪د╪ص╪» ┘╪▒┘ê╪┤/╪ذ╪│╪ز┘çظî╪ذ┘╪»█î',
  `quantity_per_packaging` int(10) unsigned NOT NULL DEFAULT 1 COMMENT '╪ز╪╣╪»╪د╪» ╪»╪▒ ┘ç╪▒ ┘ê╪د╪ص╪» ┘╪▒┘ê╪┤ (┘à╪س┘╪د┘ï: 4 ╪╣╪»╪» ╪»╪▒ ┌ر╪د╪▒╪ز┘)',
  `is_active` tinyint(1) NOT NULL DEFAULT 0,
  `is_featured` tinyint(1) NOT NULL DEFAULT 0,
  `status` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `view_count` bigint(20) unsigned NOT NULL DEFAULT 0,
  `seo_title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `seo_description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `seo_keywords` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `seo_canonical_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `products_slug_unique` (`slug`),
  UNIQUE KEY `products_sku_unique` (`sku`),
  UNIQUE KEY `products_legacy_id_unique` (`legacy_id`),
  KEY `products_supplier_id_is_active_index` (`supplier_id`,`is_active`),
  KEY `products_category_id_is_active_index` (`category_id`,`is_active`),
  KEY `products_status_index` (`status`),
  KEY `products_is_featured_is_active_index` (`is_featured`,`is_active`),
  KEY `products_created_at_index` (`created_at`),
  KEY `products_is_active_status_index` (`is_active`,`status`),
  KEY `products_category_active_status_idx` (`category_id`,`is_active`,`status`),
  KEY `products_sku_idx` (`sku`),
  FULLTEXT KEY `products_title_short_description_fulltext` (`title`,`short_description`),
  CONSTRAINT `products_category_id_foreign` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`),
  CONSTRAINT `products_supplier_id_foreign` FOREIGN KEY (`supplier_id`) REFERENCES `suppliers` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=949 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
